/* Evidence viewer only: detection results are generated by the Python analyzer. */
(function(root){
  'use strict';
  const data=root.ADInvestigation,panel=document.querySelector('[data-ad-case]');
  if(!data||!panel||!root.PortfolioReplay)return;
  const $=s=>panel.querySelector(s), esc=v=>String(v??'missing').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const records=new Map(data.records.map(r=>[r.id,r])),packets=new Map(data.packets.map(p=>[p.id,p]));
  const phases=['spray','tickets','shares','remote'];
  const logic={spray:'Security 4625 · ≥5 distinct target accounts / inclusive 15 s · group host + caller account + PID + logon session. PID association to a process start is bounded to 60 s; no GUID exists in 4625.',tickets:'Security 4769 · status 0x0 + RC4 0x17 · ≥5 distinct non-machine services / 15 s · same DC + principal + client IP. Exclude machine names ending $ and krbtgt.',shares:'Security 5145 · IPC$ + srvsvc · ≥2 target hosts / 15 s · same account + client IP. Discovery context, not proof of the RPC operation or data theft.',remote:'Sysmon 1 · powershell.exe child / wsmprovhost.exe parent · same host + exact parent GUID + account + session · parent age 0–10 s. 4624 type 3 joins the target logon (−2…15 s). Client Sysmon 3 + TCP tuple + time corroborate contact; there is no end-to-end request ID.'};
  let phase=0,selected=null,visible=[],running=false,replay;
  const primary=s=>records.get(s.facts.child_record||s.facts.failure_records?.[0]||s.record_ids[0]);
  const fieldList=values=>'<dl class="field-list">'+Object.entries(values).map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(typeof v==='object'&&v!==null?JSON.stringify(v):v)+'</dd></div>').join('')+'</dl>';
  function inspect(id){
    selected=id;
    panel.querySelectorAll('[data-ad-record]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.adRecord===id)));
    const r=records.get(id),p=packets.get(id);
    if(r){
      $('[data-ad-inspector]').innerHTML='<h3>'+esc(r.id)+' / '+esc(r.provider=== 'Microsoft-Windows-Sysmon'?'Sysmon':'Security')+' '+r.event_id+'</h3>'+fieldList({'Host':r.host,'Account':r.actor,'Event time':r.event_time,'Collection time':r.collection_time,'Delay (seconds)':r.delay_seconds,'Clock basis':r.clock_basis,'Precision':r.time_precision,'Logon session':r.session,'Process GUID':r.guid||null,'Source line':r.line,'Record number':r.record_number,'Original-line SHA-256':r.raw_sha256})+'<details class="logic-drawer"><summary>Original field excerpt</summary><pre tabindex="0"><code>'+esc(JSON.stringify(r.raw,null,2))+'</code></pre></details>';
    }else if(p){
      $('[data-ad-inspector]').innerHTML='<h3>'+esc(p.id)+' / PCAP packet '+p.packet_number+'</h3>'+fieldList({'UTC':p.event_time,'Transport':p.protocol,'Source':p.source_ip+':'+p.source_port,'Destination':p.destination_ip+':'+p.destination_port,'HTTP request':p.http_request,'PCAP byte offset':p.byte_offset,'Captured bytes':p.captured_bytes,'Frame SHA-256':p.frame_sha256})+'<p class="decision-reason">Exact client flow tuple, bounded time. Packet-to-process causation is not established. Retransmissions are not deduplicated.</p>';
    }
  }
  function chart(){
    const clock=$('[data-ad-clock]').value,base=Date.parse('2020-10-22T08:29:50Z');
    let svg='<desc>Findings positioned on a fixed UTC time axis. Collection time exposes delayed DC telemetry.</desc>';
    for(let t=0;t<=50;t+=10){const x=205+t/53*575;svg+='<path class="ad-grid" d="M'+x+' 20V245"/><text class="chart-time" x="'+x+'" y="270">'+new Date(base+t*1000).toISOString().slice(11,19)+'</text>';}
    if(!$('[data-ad-timeline] [data-ad-point]')){
      data.signals.forEach((s,i)=>{const y=38+i*39,label=['Failures / WS5','RC4 / DC','IPC$ / 3 hosts','PowerShell / WS6','PowerShell / WS7','PowerShell / DC'][i];svg+='<text class="chart-note" x="8" y="'+(y+4)+'">'+label+'</text><path class="ad-track" d="M205 '+y+'H790"/><g class="ad-time-dot" data-ad-point="'+i+'"><circle r="6"/><title></title></g>';});
      $('[data-ad-timeline]').innerHTML=svg;
    }
    data.signals.forEach((s,i)=>{const r=primary(s),x=205+(Date.parse(r[clock])-base)/53000*575,y=38+i*39,g=$('[data-ad-point="'+i+'"]');g.style.transform='translate('+x+'px,'+y+'px)';g.classList.toggle('is-active',s.phase===phases[phase]);g.querySelector('circle').setAttribute('r',s.phase===phases[phase]?8:5);g.querySelector('title').textContent=s.title+' · '+r[clock]+' · '+r.id;});
    $('[data-ad-clock-label]').textContent=(clock==='event_time'?'Event time':'Collection time')+' · 2020-10-22 UTC';
  }
  function render(){
    const controls=$('[data-ad-view]').value==='controls';
    const list=data.signals.filter(s=>s.phase===phases[phase]);
    const signal=list.find(s=>s.facts.host===$('[data-ad-target]').value)||list[0];
    $('[data-ad-target]').disabled=phase!==3||controls;
    panel.querySelectorAll('[data-ad-phase]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.adPhase===phase)));
    if(controls){
      visible=data.records.filter(r=>r.provider==='Microsoft-Windows-Security-Auditing'&&r.event_id===4769&&!data.signals.find(s=>s.rule==='RC4_SERVICE_BURST').record_ids.includes(r.id)).map(r=>r.id);
      $('[data-ad-summary]').innerHTML='<h3>Twelve ticket records excluded from the RC4 burst</h3><p>These are actual captured 4769 records: encryption, machine-service or principal fields differ from the qualifying group. Exclusion from this rule is not a verdict that all activity is benign.</p>';
      $('[data-ad-outcome]').textContent='Control evidence · 12 nonmatching tickets. Inspect 0x12 AES, machine services and principal context.';
    }else{
      visible=[...signal.record_ids,...(signal.facts.packet_ids||[])];
      const facts={...signal.facts};
      for(const name of ['failure_records','network_records','packet_ids','target_ips'])if(Array.isArray(facts[name]))facts[name.replace('_ids','').replace('_records','')+' count']=facts[name].length;
      for(const name of ['failure_records','network_records','packet_ids','target_ips'])delete facts[name];
      $('[data-ad-summary]').innerHTML='<h3>'+esc(signal.title)+'</h3>'+fieldList(facts)+'<p>'+esc(signal.limits)+'</p>';
      $('[data-ad-outcome]').textContent=phase===3?'Direct process/logon joins + tuple/time-associated WSMan contact. Legitimate administration remains possible.':signal.limits;
    }
    $('[data-ad-logic]').textContent=logic[phases[phase]];
    $('[data-ad-records]').innerHTML=visible.map(id=>{const r=records.get(id),p=packets.get(id);return '<button type="button" data-ad-record="'+id+'" aria-pressed="false"><span>'+id+'</span><strong>'+esc(r?(r.provider==='Microsoft-Windows-Sysmon'?'Sysmon ':'Security ')+r.event_id+' / '+r.host.split('.')[0]:'PCAP / '+p.destination_ip)+'</strong><span>'+esc(r?r.event_time.slice(11,23)+' · '+(r.raw.Image?.split('\\').pop()||r.target_account||r.service||r.actor):p.http_request)+'</span></button>';}).join('');
    const first=controls?visible[0]:signal.facts.child_record||signal.facts.failure_records?.[0]||visible[0];
    inspect(first);chart();
  }
  panel.addEventListener('click',e=>{
    const record=e.target.closest('[data-ad-record]'),button=e.target.closest('[data-ad-phase]');
    if(record){if(replay)replay.pause();inspect(record.dataset.adRecord);}
    if(button){$('[data-ad-view]').value='findings';replay.select(+button.dataset.adPhase);render();}
  });
  $('[data-ad-clock]').addEventListener('change',chart);
  $('[data-ad-view]').addEventListener('change',()=>{if($('[data-ad-view]').value==='controls')replay.select(1);render();});
  $('[data-ad-target]').addEventListener('change',render);
  replay=root.PortfolioReplay.createReplay({count:4,intervalMs:2200,element:panel,onChange:(index,isRunning)=>{
    const changed=phase!==index;phase=index;running=isRunning;panel.dataset.running=String(running);$('[data-ad-play]').textContent=running?'Pause':'Play';
    if(changed||!visible.length)render();
  }});
  $('[data-ad-play]').addEventListener('click',()=>{if(running)replay.pause();else{$('[data-ad-view]').value='findings';render();replay.play();}});
  $('[data-ad-step]').addEventListener('click',()=>{$('[data-ad-view]').value='findings';replay.step();});
  $('[data-ad-reset]').addEventListener('click',()=>{$('[data-ad-view]').value='findings';replay.reset();render();});
  panel.querySelectorAll('[data-enhanced]').forEach(e=>e.hidden=false);
})(globalThis);
